#define STRICT_LIBRARY
#include "strict.cpp"
#undef main
string flip(string s){auto p=s.find('v');return s.substr(p+1)+"v"+s.substr(0,p);}
struct E{long long n=0;string f,m;int d=0;set<int> distances;};
int main(){init();setup();load();loadD();atomic<int> job{0};mutex mu;ofstream of("strict_edges_canon.tsv"),stat("audit_stats.tsv"),hist("distance_hist.tsv");vector<thread> th;for(int w=0;w<4;w++)th.emplace_back([&]{for(;;){int id=job++;if(id>=int(ts.size()))break;auto&t=ts[id];auto&d=ds[id];map<tuple<string,int>,E> es;map<pair<int,int>,long long> h;long long states=0,all=0,wdl=0,strict=0,inf=0;for(U a=0;a<(U)t.sz;a++){int z=t.v[a];Pos p=dec(t,a);assert((z!=INV)==valid(t,p));if(z==INV)continue;states++;h[{pc(z),d[a]}]++;if(z==DEAD){assert(d[a]==0);continue;}bool loser=z!=0&&z!=(p.turn?-1:1);int mn=INF,mx=0,tot=0,eligible=0;bool finite=false;moves(t,p,[&](Move m,Pos v){tot++;auto[j,q]=child(t,p,m,v);U b=enc(ts[j],q);int y=pc(ts[j].v[b])*(q.turn!=1-p.turn?-1:1);assert(ts[j].v[b]!=INV);if(y!=z){assert(!loser);return;}eligible++;wdl++;D dd=ds[j][b];if(dd!=INF){finite=true;mn=min(mn,int(dd)+1);mx=max(mx,int(dd)+1);}else assert(!loser);bool opt=(d[a]!=INF&&dd!=INF&&d[a]==dd+1);if(!opt)return;strict++;if(m.cap>=0||m.pr){auto &e=es[{mat(ts[j],q.turn!=1-p.turn),z}];if(!e.n){e.f=fen(t,p);e.m=uci(p,m);e.d=d[a];}e.n++;e.distances.insert(d[a]);}});all+=tot;if(!tot){assert(d[a]==0);continue;}assert(eligible);if(d[a]==INF){assert(z==0&&!finite);inf++;}else{assert(finite);assert(d[a]==(loser?mx:mn));}}
lock_guard<mutex> lk(mu);for(auto&[k,e]:es){auto [target,z]=k;of<<t.name<<'\t'<<target<<'\t'<<z<<'\t'<<e.n<<'\t'<<e.d<<'\t'<<e.f<<'\t'<<e.m<<'\t';for(int d:e.distances)of<<d<<',';of<<'\n';}of.flush();for(auto [k,n]:h)hist<<t.name<<'\t'<<k.first<<'\t'<<k.second<<'\t'<<n<<'\n';hist.flush();stat<<t.name<<'\t'<<states<<'\t'<<all<<'\t'<<wdl<<'\t'<<strict<<'\t'<<inf<<'\n';stat.flush();cerr<<t.name<<" audit "<<states<<" "<<strict<<" edges "<<es.size()<<endl;}});for(auto&x:th)x.join();}
